<script lang="ts">
  import { goto } from '$app/navigation';
  import { useDemo } from '#lib/demo.svelte';
  import { finishes, materials, phaseNames, productById, projects } from '#lib/data';
  import { money } from '#lib/pricing';
  import type { Finish, Product } from '#lib/types';
  import Artwork from '#lib/components/Artwork.svelte';
  import DemoVideo from '#lib/components/DemoVideo.svelte';
  import Reviews from '#lib/components/Reviews.svelte';
  import ProductCard from '#lib/components/ProductCard.svelte';
  let { data }: { data: { product: Product } } = $props();
  const demo = useDemo();
  const product = $derived(data.product);
  let format = $state('400 ml'); let color = $state(''); let finish = $state<Finish>('matte'); let quantity = $state(1); let ral = $state(''); let image = $state('pack'); let zoom = $state(false);
  $effect(() => { product.id; format = product.variants[0].format; color = product.variants[0].color; finish = product.variants[0].finish; quantity = 1; ral = ''; image = 'pack'; });
  const variant = $derived(product.variants.find((v) => v.format === format && v.color === color && v.finish === finish) ?? product.variants[0]);
  const availableColors = $derived([...new Map(product.variants.map((v) => [v.color,v])).values()]);
  const availableFinishes = $derived([...new Set(product.variants.map((v) => v.finish))]);
  const compatibleProject = $derived(projects.find((p) => p.phases.some((s) => s.productId === product.id)));
  const related = $derived(product.phase === 'pinta' ? ['imprimacion-madera','barniz-acrilico','herramientas'] : product.phase === 'repara' ? ['imprimacion-madera','pintura-water-based','herramientas'] : ['pintura-water-based','barniz-acrilico','herramientas'].filter((id) => id !== product.id));
  function add(quick = false) { demo.add({ kind:'product',productId:product.id,variantId:variant.id,quantity }); if (quick) { demo.drawer = false; goto('/carrito'); } }
  const fields = [['Para qué sirve','Purpose'],['Superficies','Surfaces'],['Problema que resuelve','Problem addressed'],['Características','Characteristics'],['Dificultad','Difficulty'],['Rendimiento','Coverage'],['Número de capas','Number of coats'],['Secado','Drying'],['Acabado','Finish'],['Uso','Use']];
  const usage = [['Preparación de la superficie','Surface preparation'],['Aplicación','Application'],['Secado','Drying'],['Lijado y acabado','Sanding and finishing'],['Limpieza de herramientas','Tool cleaning'],['Precauciones','Precautions']];
</script>
<svelte:head><title>{product.name} · WEPRO Demo</title></svelte:head>
<section class="section"><div class="container"><div class="breadcrumb"><a href="/">{demo.t('Inicio','Home')}</a> / <a href="/productos">{demo.t('Productos','Products')}</a> / {product.name}</div><div class="detail-hero"><div>{#if image === 'video'}<DemoVideo title={product.name}/>{:else}<button class="text-button" style="display:block;padding:0;width:100%" aria-label={demo.t('Ampliar imagen de muestra','Enlarge sample image')} onclick={() => zoom = !zoom}><div style={zoom ? 'transform:scale(1.05)' : ''}><Artwork kind={image === 'pack' ? 'product' : compatibleProject?.material ?? 'table'} color={variant.hex} phase={product.phase} label={product.name + ' · demo'}/></div></button>{/if}<div class="gallery"><button class="secondary" onclick={() => image = 'pack'}>{demo.t('Producto','Product')}</button><button class="secondary" onclick={() => image = 'application'}>{demo.t('Aplicación demo','Demo application')}</button><button class="secondary" onclick={() => image = 'video'}>{demo.t('Vídeo demo','Demo video')}</button></div><p class="muted" style="margin-top:15px">{demo.t('Ilustración local de muestra. Pulsa la imagen para ampliar.','Local sample illustration. Click the image to enlarge.')}</p></div><div><div class="eyebrow">{phaseNames[product.phase][demo.state.language]} · {product.base} · DEMO</div><h1>{product.name}</h1><p>{demo.t('Referencia de ejemplo para recorrer la selección y compra local.','Sample reference for exploring local selection and shopping.')}</p><a href="#valoraciones">★★★★★ · {demo.t('Valoración ficticia','Fictional rating')}</a><div class="price">{money(variant.price,demo.state.language)}</div><p class="muted">{money(variant.price / (format === '400 ml' ? 4 : 2),demo.state.language)} / 100 ml · {demo.t('IVA de muestra incluido','Sample tax included')}</p><p>{variant.stock ? `● ${demo.t('En stock demo','In demo stock')} (${variant.stock})` : demo.t('Agotado demo','Out of stock demo')} · {demo.t('Envío simulado 3–5 días UE / 7–10 EE. UU.','Simulated delivery 3–5 days EU / 7–10 US')}</p><label>{demo.t('Formato','Format')}<select bind:value={format}>{#each [...new Set(product.variants.map((v) => v.format))] as f}<option>{f}</option>{/each}</select></label><p style="margin-top:20px">{demo.t('Color de muestra','Sample color')}: <strong>{variant.color} {variant.ral ? `RAL ${variant.ral}` : ''}</strong></p><div class="swatches">{#each availableColors as c}<button aria-label={c.color + (c.ral ? ` RAL ${c.ral}` : '')} aria-pressed={color === c.color} class:selected={color === c.color} style={`background:${c.hex}`} onclick={() => color = c.color}></button>{/each}</div>{#if availableColors.some((v) => v.ral)}<form onsubmit={(e) => { e.preventDefault(); const match = availableColors.find((v) => v.ral === ral.replace(/\D/g,'')); if (match) { color = match.color; demo.notice = demo.t('Color demo seleccionado','Demo color selected'); } else demo.notice = demo.t('RAL no incluido en la muestra. Prueba 9010, 6003, 8004, 5008 o 9005.','RAL not included in sample. Try 9010, 6003, 8004, 5008 or 9005.'); }} class="row"><label class="grow">{demo.t('Buscar RAL de muestra','Search sample RAL')}<input bind:value={ral} placeholder="6003"/></label><button class="secondary">{demo.t('Buscar','Search')}</button></form>{/if}<label style="margin:20px 0">{demo.t('Acabado','Finish')}<select bind:value={finish}>{#each availableFinishes as f}<option value={f}>{finishes[f][demo.state.language]}</option>{/each}</select></label><div class="row"><div class="quantity"><button disabled={quantity <= 1} aria-label={demo.t('Reducir cantidad','Decrease quantity')} onclick={() => quantity = Math.max(1,quantity-1)}>−</button><span>{quantity}</span><button aria-label={demo.t('Aumentar cantidad','Increase quantity')} onclick={() => quantity++}>+</button></div>{#if variant.stock}<button class="grow" onclick={() => add()}>{demo.t('Añadir al carrito','Add to cart')}</button>{:else}<button class="grow" onclick={() => { if (!demo.state.notifications.includes(variant.id)) demo.state.notifications.push(variant.id); demo.notice = demo.t('Aviso simulado guardado localmente. No se enviará email.','Simulated notification saved locally. No email will be sent.'); }}>{demo.t('Avísame · simulación','Notify me · simulation')}</button>{/if}<button class="secondary" aria-label={demo.t('Guardar producto','Save product')} onclick={() => demo.favorite(product.id)}>{demo.state.wishlist.includes(product.id) ? '♥' : '♡'}</button></div><button class="secondary wide" disabled={!variant.stock} style="margin-top:15px" onclick={() => add(true)}>{demo.t('Compra rápida · simulada','Quick buy · simulated')}</button>{#if compatibleProject}<div class="callout"><h3>{demo.t('¿Lo usas en un proyecto?','Using it in a project?')}</h3><a href={`/proyectos/${compatibleProject.id}#kit`}>{compatibleProject.title[demo.state.language]} →</a></div>{/if}</div></div></div></section>
<section class="section cream"><div class="container"><h2>{demo.t('Información práctica de muestra','Sample practical information')}</h2><p class="demo-note">{demo.t('No es una ficha técnica aprobada. Los números siguientes son ficticios.','This is not an approved technical sheet. The numbers below are fictional.')}</p><div class="grid cols-5">{#each fields as f,i}<div class="card card-body"><div class="eyebrow">0{i+1}</div><h3>{demo.t(f[0],f[1])}</h3><p class="muted">{i === 1 ? product.materials.map((m) => materials[m][demo.state.language]).join(', ') : i === 5 ? '2 m² / 400 ml · demo' : i === 6 ? '2 · demo' : i === 7 ? '45 min / 24 h · demo' : i === 8 ? finishes[variant.finish][demo.state.language] : demo.t('Contenido de ejemplo pendiente de validación.','Example content pending validation.')}</p></div>{/each}</div></div></section>
<section class="section"><div class="container grid cols-2"><div><h2>{demo.t('Cómo utilizarlo · ejemplo','How to use · example')}</h2>{#each usage as u,i}<div class="step"><div class="row"><span class="step-number">{i+1}</span><h3 style="margin:0">{demo.t(u[0],u[1])}</h3></div><p class="muted" style="margin-top:15px">{demo.t('Paso ilustrativo del flujo. Consultar instrucciones aprobadas antes de una aplicación real.','Illustrative flow step. Consult approved instructions before real application.')}</p></div>{/each}</div><div><DemoVideo title={product.name}/><h2 style="margin-top:25px">{demo.t('Descargas de muestra','Sample downloads')}</h2>{#each [['técnica','Technical sheet'],['seguridad','Safety sheet'],['instrucciones','Instructions'],['certificados','Certificates'],['colores','Color chart']] as doc}<a class="door" style="margin:12px 0" href={`/guia?type=${doc[0]}&product=${product.id}`}>{demo.t(`Documento de ${doc[0]} · muestra`,`${doc[1]} · sample`)} <span>↗</span></a>{/each}</div></div></section>
<section class="section cream"><div class="container"><h2>{demo.t('Completa las fases de tu proyecto','Complete your project phases')}</h2><p class="muted">{demo.t('Relaciones de muestra: preparación, siguiente fase y accesorios.','Sample relations: preparation, next phase and tools.')}</p><div class="grid cols-3">{#each related as id}<ProductCard product={productById(id)}/>{/each}</div></div></section><section class="section"><div class="container"><Reviews target={product.id}/></div></section>
